(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const out = {};
  // 等导入结果（成功提示 / 错误提示都算有反馈）
  for (let i = 0; i < 24; i++) {
    await sleep(500);
    if (document.querySelector('.pj-title') || document.querySelector('.tb-error') || document.querySelector('.pj-toast')) break;
  }
  out.openedWork = document.querySelector('.pj-title')?.textContent || null;
  out.error = document.querySelector('.tb-error')?.textContent || document.querySelector('.pj-toast')?.textContent || null;
  out.stillOnList = !!document.querySelector('.tb-actions');
  out.crashed = !document.body.innerText.trim();
  out.consoleHint = 'ok';
  return JSON.stringify(out);
})()
